-- Synthetic fixtures: Docker/local ONLY, via yarn test:h03:sql. Never --linked.
begin;
\ir helpers/auth-session.psql
create extension if not exists pgtap with schema extensions;
select extensions.plan(1);
create function pg_temp.expect(value boolean,label text) returns void language plpgsql as $$
begin if value is distinct from true then raise exception 'H03 acceptance failed: %',label; end if; end $$;
create function pg_temp.command(org uuid,op text,input jsonb,req uuid default gen_random_uuid()) returns jsonb language plpgsql as $$
declare response jsonb;
begin response := public.h03_command(org,req,op,input); if not coalesce((response->>'ok')::boolean,false) then raise exception 'H03 % failed: %',op,response; end if; return response->'data'; end $$;
\ir helpers/document-upload.psql
do $$
declare org uuid:=gen_random_uuid(); actor uuid:=gen_random_uuid(); reviewer uuid:=gen_random_uuid(); client_user uuid:=gen_random_uuid();
  client_sid uuid:=gen_random_uuid(); reviewer_sid uuid:=gen_random_uuid(); company uuid; client_member uuid; reviewer_member uuid;
  client_role uuid; internal_role uuid; dtype uuid; rule uuid; obligation uuid; first_slot public.deliverables; second_slot public.deliverables;
  result jsonb; input jsonb; requirement_input jsonb; cancel_rule uuid; cancelled_obligation uuid; req uuid:=gen_random_uuid(); download_req uuid:=gen_random_uuid(); intent1 uuid; intent2 uuid; correction uuid; previous_receipt timestamptz; expired_intent uuid:=gen_random_uuid(); validating_intent uuid:=gen_random_uuid(); previous_claims text;
begin
  insert into auth.users(id,email) values(actor,'h03-a-'||actor||'@example.test'),(reviewer,'h03-r-'||reviewer||'@example.test'),(client_user,'h03-c-'||client_user||'@example.test');
  insert into public.profiles(user_id,email,full_name,provisioning_status) select id,email,'H03 synthetic','ready' from auth.users where id in(actor,reviewer,client_user);
  insert into public.organizations(id,name) values(org,'H03 SQL');
  insert into public.organization_members(organization_id,user_id,member_type,is_admin) values(org,actor,'internal',true);
  insert into public.organization_members(organization_id,user_id,member_type,is_admin) values(org,reviewer,'internal',true) returning id into reviewer_member;
  insert into public.organization_members(organization_id,user_id,member_type) values(org,client_user,'client') returning id into client_member;
  insert into public.companies(organization_id,ruc,legal_name,control_start_date) values(org,'20999999888','H03 company',(now() at time zone 'America/Lima')::date) returning id into company;
  insert into public.roles(organization_id,code,name,audience) values(org,'h03_client','Client','client') returning id into client_role;
  insert into public.roles(organization_id,code,name,audience) values(org,'h03_review','Reviewer','internal') returning id into internal_role;
  insert into public.permissions(organization_id,module,action,description) select org,'tributario',action,action from unnest(array['view','upload','download','approve','observe','reopen','waive']) action;
  insert into public.role_permissions(organization_id,role_id,permission_id) select org,client_role,id from public.permissions where organization_id=org and action in ('view','upload','download');
  insert into public.role_permissions(organization_id,role_id,permission_id) select org,internal_role,id from public.permissions where organization_id=org and action in ('view','download','approve','observe','reopen','waive');
  insert into public.access_grants(organization_id,member_id,scope,company_id,module,role_id) values(org,client_member,'company',company,'tributario',client_role),(org,reviewer_member,'company',company,'tributario',internal_role);
  insert into public.company_module_settings(organization_id,company_id,module,delivery_responsible_id) values(org,company,'tributario',client_user);
  perform pg_temp.authenticate('{"role":"service_role"}',true);
  begin perform public.h02_admin_prepare(org,actor,gen_random_uuid(),'SetUserEnabled',repeat('b',64),actor); raise exception 'Self-disable accepted'; exception when raise_exception then if sqlerrm<>'FORBIDDEN' then raise; end if; end;
  perform pg_temp.expect((select enabled from public.profiles where user_id=actor),'H02 self-disable rejected before staging');
  perform pg_temp.authenticate(jsonb_build_object('sub',actor,'role','authenticated','session_id',gen_random_uuid())::text,true);
  dtype := (pg_temp.command(org,'SaveDocumentType','{"code":"pdt-test","name":"PDT test","module":"tributario","suggested_formats":["pdf"],"active":true}')->>'resource_id')::uuid;
  input:=jsonb_build_object('document_type_id',dtype,'company_id',company,'title','PDT two files','deadline_offset_days',0,'allowed_formats',jsonb_build_array('pdf'),'max_file_bytes',20000000,'deliverable_specs',
    '[{"position_code":"pdt_1","label":"PDT first","display_order":1,"allowed_formats":["pdf"],"max_file_bytes":20000000},{"position_code":"pdt_2","label":"PDT second","display_order":2,"allowed_formats":["pdf"],"max_file_bytes":20000000}]'::jsonb);
  requirement_input := input;
  rule := (pg_temp.command(org,'ConfigureRequirement',input)->>'resource_id')::uuid;
  obligation := (pg_temp.command(org,'GenerateMonthly',jsonb_build_object('rule_id',rule))->>'resource_id')::uuid;
  perform pg_temp.command(org,'GenerateMonthly',jsonb_build_object('rule_id',rule));
  perform pg_temp.expect((select count(*)=1 from public.obligations where rule_id=rule),'one monthly obligation');
  perform pg_temp.expect((select count(*)=2 from public.deliverables where obligation_id=obligation),'two positions');
  select * into first_slot from public.deliverables where obligation_id=obligation and display_order=1;
  select * into second_slot from public.deliverables where obligation_id=obligation and display_order=2;
  perform pg_temp.authenticate(jsonb_build_object('sub',client_user,'role','authenticated','session_id',client_sid)::text,true);
  input:=jsonb_build_object('deliverable_id',first_slot.id,'cycle_id',(select id from public.submission_cycles where deliverable_id=first_slot.id and state='open'),'expected_revision',0,'original_name','first.pdf','declared_bytes',200,'declared_mime','application/octet-stream');
  intent1:=(pg_temp.command(org,'CreateUploadIntent',input,req)->>'resource_id')::uuid;
  result:=public.h03_command(org,gen_random_uuid(),'CreateUploadIntent',input||'{"declared_bytes":20000001}');
  perform pg_temp.expect(result->'error'->>'code'='FILE_TOO_LARGE','snapshot byte limit');
  perform pg_temp.expect((pg_temp.command(org,'CreateUploadIntent',input,req)->>'resource_id')::uuid=intent1,'reservation retry');
  result:=public.h03_command(org,req,'CreateUploadIntent',input||'{"original_name":"changed.pdf"}');
  perform pg_temp.expect(result->'error'->>'code'='CONFLICT','request input mismatch');
  perform pg_temp.expect((select current_version_id is null from public.deliverables where id=first_slot.id),'reservation is not delivery');
  perform pg_temp.confirm(intent1,client_user,client_sid);
  select first_submitted_at into previous_receipt from public.submission_cycles where deliverable_id=first_slot.id and cycle_number=1;
  result:=pg_temp.command(org,'CreateUploadIntent',input||'{"expected_revision":1}',gen_random_uuid());
  perform pg_temp.confirm((result->>'resource_id')::uuid,client_user,client_sid);
  perform pg_temp.expect((select first_submitted_at=previous_receipt from public.submission_cycles where deliverable_id=first_slot.id and cycle_number=1),'replacement preserves first receipt');
  intent2:=(pg_temp.command(org,'CreateUploadIntent',jsonb_build_object('deliverable_id',second_slot.id,'cycle_id',(select id from public.submission_cycles where deliverable_id=second_slot.id and state='open'),'expected_revision',0,'original_name','second.pdf','declared_bytes',200,'declared_mime','application/pdf'))->>'resource_id')::uuid;
  perform pg_temp.confirm(intent2,client_user,client_sid);
  perform pg_temp.expect((select not overdue and operational_due_date is null and aggregate_state='por_revisar' from public.h03_obligation_summary where id=obligation),'timely pending review is not overdue');
  select * into first_slot from public.deliverables where id=first_slot.id;
  select * into second_slot from public.deliverables where id=second_slot.id;
  result:=public.h03_command(org,gen_random_uuid(),'ApproveVersion',jsonb_build_object('deliverable_id',first_slot.id,'version_id',first_slot.current_version_id,'expected_revision',first_slot.revision));
  perform pg_temp.expect(result->'error'->>'code'='NOT_FOUND','client cannot approve');
  perform pg_temp.authenticate(jsonb_build_object('sub',reviewer,'role','authenticated','session_id',reviewer_sid)::text,true);
  input:=jsonb_build_object('deliverable_id',first_slot.id,'version_id',first_slot.current_version_id,'expected_revision',first_slot.revision);
  perform pg_temp.command(org,'ApproveVersion',input);
  result:=public.h03_command(org,gen_random_uuid(),'ApproveVersion',input);
  perform pg_temp.expect(result->'error'->>'code'='CONFLICT','stale reviewer rejected');
  perform pg_temp.expect((select approved_count=1 and total_count=2 and aggregate_state<>'aprobado' from public.h03_obligation_summary where id=obligation),'partial approval 1/2');
  perform pg_temp.command(org,'RequestDownload',jsonb_build_object('version_id',first_slot.current_version_id),download_req);
  update public.role_permissions rp set deleted_at=now(),deleted_by=actor,deletion_reason='Revocation fixture' from public.permissions p where rp.permission_id=p.id and rp.role_id=internal_role and p.action='download';
  result:=public.h03_command(org,download_req,'RequestDownload',jsonb_build_object('version_id',first_slot.current_version_id));
  perform pg_temp.expect(result->'error'->>'code'='NOT_FOUND','download retry rechecks current capability');
  update public.role_permissions set deleted_at=null,deleted_by=null,deletion_reason=null where role_id=internal_role;
  input:=jsonb_build_object('deliverable_id',second_slot.id,'version_id',second_slot.current_version_id,'expected_revision',second_slot.revision,'comment','Correct the document','new_due_date',(now() at time zone 'America/Lima')::date+1);
  perform pg_temp.command(org,'ObserveVersion',input);
  perform pg_temp.expect((select payload->>'due_date'=input->>'new_due_date' from public.notification_events where organization_id=org and event_type='observed'),'observed event carries correction deadline');
  perform pg_temp.expect((select state='closed' and first_submitted_at is not null from public.submission_cycles where deliverable_id=second_slot.id and cycle_number=1),'observation preserves original cycle');
  perform pg_temp.expect((select reason='correction' and first_submitted_at is null from public.submission_cycles where deliverable_id=second_slot.id and cycle_number=2),'new correction cycle');
  select * into second_slot from public.deliverables where id=second_slot.id;
  perform pg_temp.authenticate(jsonb_build_object('sub',client_user,'role','authenticated','session_id',client_sid)::text,true);
  correction:=(pg_temp.command(org,'CreateUploadIntent',jsonb_build_object('deliverable_id',second_slot.id,'cycle_id',(select id from public.submission_cycles where deliverable_id=second_slot.id and state='open'),'expected_revision',second_slot.revision,'original_name','correction.pdf','declared_bytes',200,'declared_mime','application/pdf'))->>'resource_id')::uuid;
  perform pg_temp.confirm(correction,client_user,client_sid);
  select * into second_slot from public.deliverables where id=second_slot.id;
  perform pg_temp.authenticate(jsonb_build_object('sub',reviewer,'role','authenticated','session_id',reviewer_sid)::text,true);
  perform pg_temp.command(org,'ApproveVersion',jsonb_build_object('deliverable_id',second_slot.id,'version_id',second_slot.current_version_id,'expected_revision',second_slot.revision));
  perform pg_temp.expect((select aggregate_state='aprobado' and approved_count=2 from public.h03_obligation_summary where id=obligation),'complete after individual approvals');
  select * into first_slot from public.deliverables where id=first_slot.id;
  input:=jsonb_build_object('deliverable_id',first_slot.id,'version_id',first_slot.current_version_id,'expected_revision',first_slot.revision,'comment','Reopen fixture','new_due_date',(now() at time zone 'America/Lima')::date+2);
  perform pg_temp.command(org,'ReopenApproved',input);
  perform pg_temp.expect((select current_version_id is null and review_state='pendiente' from public.deliverables where id=first_slot.id),'reopening requires new version');
  perform pg_temp.expect((select count(*)=2 from public.review_events where version_id=first_slot.current_version_id),'prior approval and reopening conserved');
  result:=public.h03_query(org,'history',jsonb_build_object('id',obligation));
  perform pg_temp.expect((result->>'ok')::boolean and (result->'data'->>'count')::integer=4,'paginated history');
  result:=public.h03_command(org,gen_random_uuid(),'SetNotApplicable',jsonb_build_object('obligation_id',obligation,'expected_revision',(select revision from public.obligations where id=obligation),'reason',''));
  perform pg_temp.expect(result->'error'->>'code'='VALIDATION_ERROR','disposition requires reason');
  perform pg_temp.command(org,'SetNotApplicable',jsonb_build_object('obligation_id',obligation,'expected_revision',(select revision from public.obligations where id=obligation),'reason','Not applicable fixture'));
  perform pg_temp.expect((select disposition='no_aplica' and not overdue from public.h03_obligation_summary where id=obligation),'exclusion without deleting history');
  begin update public.obligations set snapshot='{}' where id=obligation; raise exception 'Snapshot mutated'; exception when raise_exception then if sqlerrm<>'FORBIDDEN' then raise; end if; end;
  insert into public.upload_intents(id,organization_id,deliverable_id,cycle_id,user_id,request_id,reserved_version_id,expected_deliverable_revision,original_name,declared_bytes,declared_mime,staging_path,final_path,created_at,expires_at,state,validation_token,validation_lease_until)
    select new_id,org,deliverable_id,cycle_id,user_id,gen_random_uuid(),gen_random_uuid(),expected_deliverable_revision,original_name,declared_bytes,declared_mime,new_id::text,new_id::text,
      now()-interval '26 hours',now()-interval '2 hours',case when new_id=validating_intent then 'validating' else 'reserved' end,
      case when new_id=validating_intent then gen_random_uuid() end,case when new_id=validating_intent then now()+interval '2 minutes' end
    from public.upload_intents cross join unnest(array[expired_intent,validating_intent]) new_id where id=intent2;
  previous_claims:=current_setting('request.jwt.claims'); perform pg_temp.authenticate('{"role":"service_role"}',true);
  perform public.h03_expire_uploads();
  perform pg_temp.expect((select state='expired' and confirmed_version_id is null from public.upload_intents where id=expired_intent),'expired staging retained as metadata');
  perform pg_temp.expect((select state='validating' from public.upload_intents where id=validating_intent),'active validator excluded from cleanup');
  perform pg_temp.expect((select state='ready' from public.upload_intents where id=intent2),'confirmed version excluded from cleanup');
  perform pg_temp.authenticate(previous_claims,true);
  perform pg_temp.authenticate(jsonb_build_object('sub',actor,'role','authenticated','session_id',gen_random_uuid())::text,true);
  cancel_rule := (pg_temp.command(org,'ConfigureRequirement',requirement_input||'{"title":"Cancellation fixture"}')->>'resource_id')::uuid;
  cancelled_obligation := (pg_temp.command(org,'GenerateMonthly',jsonb_build_object('rule_id',cancel_rule))->>'resource_id')::uuid;
  perform pg_temp.authenticate(jsonb_build_object('sub',client_user,'role','authenticated','session_id',client_sid)::text,true);
  result := public.h03_command(org,gen_random_uuid(),'CancelObligation',jsonb_build_object('obligation_id',cancelled_obligation,'expected_revision',0,'reason','Client cannot cancel'));
  perform pg_temp.expect(result->'error'->>'code'='FORBIDDEN','cancellation requires administrator');
  perform pg_temp.authenticate(jsonb_build_object('sub',actor,'role','authenticated','session_id',gen_random_uuid())::text,true);
  perform pg_temp.command(org,'CancelObligation',jsonb_build_object('obligation_id',cancelled_obligation,'expected_revision',0,'reason','Generated as a synthetic cancellation fixture'));
  perform pg_temp.expect((select disposition='cancelled' from public.obligations where id=cancelled_obligation),'audited cancellation preserves obligation');
  perform pg_temp.command(org,'DeleteDocumentEntity',jsonb_build_object('entity','requirement_rules','id',cancel_rule,'expected_revision',1,'reason','Delete rule fixture'));
  update public.companies set deleted_at=now(),deleted_by=actor,deletion_reason='Parent deletion fixture' where id=company;
  result:=public.h03_command(org,gen_random_uuid(),'RestoreDocumentEntity',jsonb_build_object('entity','requirement_rules','id',cancel_rule,'expected_revision',2));
  perform pg_temp.expect(result->'error'->>'code'='FORBIDDEN','deleted parent blocks rule restoration');
  update public.companies set deleted_at=null,deleted_by=null,deletion_reason=null where id=company;
  perform pg_temp.expect((select deleted_at is not null from public.requirement_rules where id=cancel_rule),'parent restoration does not restore separately deleted rule');
  perform pg_temp.command(org,'RestoreDocumentEntity',jsonb_build_object('entity','requirement_rules','id',cancel_rule,'expected_revision',2));
  perform pg_temp.expect(not has_function_privilege('authenticated','public.h03_confirm_upload(uuid,uuid,uuid,uuid,jsonb)','EXECUTE'),'browser cannot confirm file');
  perform pg_temp.expect((select count(*)=count(distinct event_key) from public.notification_events where organization_id=org),'events without duplicates');
end $$;
select extensions.pass('H03 SQL acceptance passed; all synthetic fixtures are rolled back.');
select * from extensions.finish();
rollback;
